def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if len(pts) < 2:
        return out

    # Build a rectilinear network by repeatedly attaching the nearest
    # remaining marker to the network already made.
    connected = {pts[0]}
    remaining = set(pts[1:])

    def draw(a, b, horizontal_first):
        r1, c1 = a
        r2, c2 = b
        if horizontal_first:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                if out[r1][c] == 0:
                    out[r1][c] = 3
            for r in range(min(r1, r2), max(r1, r2) + 1):
                if out[r][c2] == 0:
                    out[r][c2] = 3
        else:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                if out[r][c1] == 0:
                    out[r][c1] = 3
            for c in range(min(c1, c2), max(c1, c2) + 1):
                if out[r2][c] == 0:
                    out[r2][c] = 3

    while remaining:
        best = None
        for p in remaining:
            for q in connected:
                d = abs(p[0] - q[0]) + abs(p[1] - q[1])
                candidate = (d, p, q)
                if best is None or candidate < best:
                    best = candidate
        _, p, q = best
        # Prefer a route that extends an existing aligned segment.
        horizontal_first = abs(p[1] - q[1]) >= abs(p[0] - q[0])
        draw(q, p, horizontal_first)
        connected.add(p)
        remaining.remove(p)

    return out
