        by_col.setdefault(c, []).append(r)

    # Use the strongest existing alignment as the main rail.
    row_choices = [(len(cs), r, cs) for r, cs in by_row.items() if len(cs) >= 2]
    col_choices = [(len(rs), c, rs) for c, rs in by_col.items() if len(rs) >= 2]

    if row_choices:
        _, rail, cs = max(row_choices)
        for c in range(min(cs), max(cs) + 1):
            if out[rail][c] == 0:
                out[rail][c] = 3
        for r, c in points:
            if r != rail:
                for rr in range(min(r, rail), max(r, rail) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    elif col_choices:
        _, rail, rs = max(col_choices)
        for r in range(min(rs), max(rs) + 1):
            if out[r][rail] == 0:
                out[r][rail] = 3
        for r, c in points:
            if c != rail:
                for cc in range(min(c, rail), max(c, rail) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
